#define CellSize vec2(350,350)
#define seed 21651.6151

#define PI 3.14159265358
#define TAU PI*2.



float hash12(vec2 p)
{
	p=p+seed;
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p)
{
	p=p+seed;
	vec3 p3 = fract((vec3(p.xyx)) * vec3(.1031, .1030, .0973));
  p3 += dot(p3, p3.yzx+33.33);
  return fract((p3.xx+p3.yz)*p3.zy);

}
float getAngle(vec2 a, vec2 b){
	vec2 m = normalize(a);
	vec2 n = normalize(b);
	return dot(m,n)*TAU;
}
float ToDeg(float radians) {
  return radians * 180.0 / 3.14159265358979323846;
}

float geometry(vec2 pos){
		vec2 cellCoord = vec2(
			floor(pos.x/CellSize.x),
			floor(pos.y/CellSize.y)
		);

		vec2 centerPoint = CellSize * cellCoord + CellSize / 2.;
		vec2 localVector = pos - centerPoint;
		float angle = getAngle(localVector, vec2(1,0));
		float d = 10.;
		for(int i=0;i<2;i++){
			float freq = 1.+hash12(centerPoint)*5.;
			float phase = hash12(centerPoint+.5)*TAU;
		  d = min(d,sin(freq*angle+phase));
		  centerPoint = hash22(centerPoint);
		}
		d = (.6+d*.4)*CellSize.x/4. - length(localVector);
		return d/(d+1.);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	vec2 translated = fragCoord.xy+vec2(iTime,iTime*.2)*200.;
	float geo = geometry(translated);

	fragColor = vec4(vec3(geo), 1.0);
}
